/// Include the code `protobus-build` generated in `build.rs`:
///
/// ```ignore
/// pub mod proto {
///     protobus::include_protos!();
/// }
/// ```
///
/// Each proto package becomes a module (`package shop.orders` is
/// `proto::shop::orders`), holding its messages, and for each service a
/// handler trait, a `<Service>Service` and a `<Service>Proxy`.
#[macro_export]
macro_rules! include_protos {
    () => {
        include!(concat!(env!("OUT_DIR"), "/protobus_gen.rs"));
    };
}
